#!/usr/bin/env bash

set -euo pipefail

# Regex: starts with wg, then any number of non-space, non-linebreak chars, then .Done()
pattern='wg[^[:space:]]*\.Done\(\)'
# Exclude: defer or // followed by any amount of letters, spaces, or dots, then wg...Done()
exclude='(defer|//)[[:space:].a-zA-Z]*wg[^[:space:]]*\.Done\(\)'
# Exclude: lines ending with //nolint:SA2000 - there is a staticcheck linter for wg.Done(), but I couldn't figure out how to enable it
nolint_exclude='//nolint:SA2000$'

excluded_files=(
    "adapters/handlers/rest/server.go"           # autogenerated
)

# Tracked .go files, excluding test files, files in tools/ or test/, and excluded_files.
# One grep over all files: spawning greps per file took minutes on this repo.
# Output lines look like "path:lineno:line".
pathspecs=('*.go' ':!:*_test.go' ':!:tools/**' ':!:test/**')
for file in "${excluded_files[@]}"; do
    pathspecs+=(":!:$file")
done
# grep exits 1 on no match (xargs turns that into 123); neither is a lint failure.
matches=$(
    git ls-files -z -- "${pathspecs[@]}" \
        | xargs -0 grep -nHE "$pattern" \
        | grep -vE "$exclude" \
        | grep -vE "$nolint_exclude" \
        || true
)

if [[ -n "$matches" ]]; then
    while IFS= read -r match; do
        echo "Error: $match" >&2
    done <<< "$matches"
    exit 1
fi
